const newVersionId = crypto.randomUUID();
const now = new Date().toISOString();

// 1. Insert into workflow_history FIRST to satisfy Foreign Key
const histStmt = db.prepare(\`
  INSERT INTO workflow_history (versionId, workflowId, authors, createdAt, updatedAt, nodes, connections, name, autosaved, description)
  VALUES (?, 'TDGPodcast0001', 'System Deployer', ?, ?, ?, ?, ?, 0, '')
\`);
histStmt.run(
  newVersionId,
  now,
  now,
  JSON.stringify(wf.nodes),
  JSON.stringify(wf.connections),
  wf.name || 'Trading Podcast AI Pipeline - Daily Studio Audio'
);

// 2. Update workflow_entity
const updateStmt = db.prepare(\`
  UPDATE workflow_entity
  SET nodes = ?,
      connections = ?,
      settings = ?,
      versionId = ?,
      activeVersionId = ?,
      active = 1,
      triggerCount = 4,
      updatedAt = ?
  WHERE id = 'TDGPodcast0001'
\`);
updateStmt.run(
  JSON.stringify(wf.nodes),
  JSON.stringify(wf.connections),
  JSON.stringify(wf.settings || {}),
  newVersionId,
  newVersionId,
  now
);

console.log('Database successfully updated to version:', newVersionId);
